  if (!isPk) return 0;
  if (hasMcExt) return 0.97;
  if (mimeMatches(intake, 'mcworld', 'mcpack', 'minecraft')) return 0.9;
  const head = intake.textSample || '';
  if (/level\.dat|levelname\.txt|db\/CURRENT|db\/MANIFEST/.test(head)) return 0.85;
