  const b = intake.bytes;
  // DICM magic at offset 128
  if (b[128] === 0x44 && b[129] === 0x49 && b[130] === 0x43 && b[131] === 0x4D) {
    return isDicomName ? 0.99 : isDicomMime ? 0.98 : 0.96;
  }
  if (isDicomName || isDicomMime) return 0.7;
  return 0;
